changeSet.sql:

if not exists (select 1 from [sys].[key_constraints] where name = 'PK_MetricAssetVersion')
begin
	ALTER TABLE [metrics].[AssetVersion] ADD CONSTRAINT PK_MetricAssetVersion PRIMARY KEY NONCLUSTERED  ( [Uid] ASC )
end

if not exists (select * from [INFORMATION_SCHEMA].[TABLE_CONSTRAINTS] where CONSTRAINT_TYPE = 'UNIQUE' and CONSTRAINT_NAME = 'UQ_MetricsAssetVersion')
begin
	ALTER TABLE [metrics].[AssetVersion] ADD CONSTRAINT UQ_MetricsAssetVersion UNIQUE ( [AssetUid] ASC, [EffectiveDate] ASC ); 
end

if not exists (select 1 from [INFORMATION_SCHEMA].[REFERENTIAL_CONSTRAINTS] where constraint_name = 'FK_MetricAssetVersion_MetricAsset')
begin
	ALTER TABLE [metrics].[AssetVersion] WITH CHECK ADD CONSTRAINT [FK_MetricAssetVersion_MetricAsset] FOREIGN KEY([AssetUid]) REFERENCES [metrics].[Asset] ([Uid]) ON DELETE CASCADE;
	ALTER TABLE [metrics].[AssetVersion] CHECK CONSTRAINT [FK_MetricAssetVersion_MetricAsset];
end

if not exists (select * from [sys].[default_constraints] where [type] = 'D' and name = 'DF_MetricAssetVersion_Uid')
begin
	ALTER TABLE [metrics].[AssetVersion] ADD  CONSTRAINT [DF_MetricAssetVersion_Uid]  DEFAULT (newid()) FOR [Uid]	
end

if not exists (select * from [sys].[default_constraints] where [type] = 'D' and name = 'DF_MetricAssetVersion_Name')
begin
	ALTER TABLE [metrics].[AssetVersion] ADD  CONSTRAINT [DF_MetricAssetVersion_Name]  DEFAULT ('') FOR [Name]
end

if not exists (select * from [sys].[default_constraints] where [type] = 'D' and name = 'DF_MetricAssetVersion_UpdateFrequency')
begin
	ALTER TABLE [metrics].[AssetVersion] ADD  CONSTRAINT [DF_MetricAssetVersion_UpdateFrequency]  DEFAULT ((0)) FOR [UpdateFrequency]	
end

if not exists (select * from [sys].[default_constraints] where [type] = 'D' and name = 'DF_MetricAssetVersion_MatchConditionsOnly')
begin
	ALTER TABLE [metrics].[AssetVersion] ADD  CONSTRAINT [DF_MetricAssetVersion_MatchConditionsOnly]  DEFAULT ((1)) FOR [MatchConditionsOnly]	
end

if not exists (select * from [sys].[default_constraints] where [type] = 'D' and name = 'DF_MetricAssetVersion_Definition')
begin
	ALTER TABLE [metrics].[AssetVersion] ADD  CONSTRAINT [DF_MetricAssetVersion_Definition]  DEFAULT ('{}') FOR [Definition]	
end
